local links = {
  CursorColumn = "CursorLine",
  SpecialKey = "NonText",
  VisualNOS = "Visual",
  IncSearch = "CurSearch",
  ["@variable.parameter"] = "@variable",
  ["@variable.parameter.builtin"] = "@variable.builtin",
  ["@module.builtin"] = "@variable.builtin",
  ["@attribute"] = "PreProc",
  ["@attribute.builtin"] = "@attribute",
}

-- The terminal colors, as in the Ghostty theme, for :terminal and lazygit.
local terminal = {
  light = { "#2d3840", "#b45648", "#3e7943", "#816a26", "#427296", "#a440bc", "#22777a", "#c1c8cc", "#506573", "#df3217", "#37863d", "#92700e", "#0f79c5", "#bf2ae3", "#0e8387", "#d8e1e7" },
  dark = { "#35424c", "#c57a6f", "#6caa71", "#c4ac62", "#6d96b4", "#bd7bcd", "#7ccbcd", "#dee5eb", "#7591a6", "#df6c5a", "#79be7e", "#e5c872", "#67b5ed", "#d389e5", "#84dde0", "#e5eff5" },
}

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end
vim.g.colors_name = "clear"

local mode = vim.o.background == "light" and "light" or "dark"
for name, spec in pairs(themes[mode]) do
  vim.api.nvim_set_hl(0, name, spec)
end
for name, target in pairs(links) do
  vim.api.nvim_set_hl(0, name, { link = target })
end
for i, color in ipairs(terminal[mode]) do
  vim.g["terminal_color_" .. (i - 1)] = color
end
